const LEVELS=['A1','A2','B1','B2'];
const LEVEL_NAMES={A1:'Первые шаги',A2:'Английский на каждый день',B1:'Говори увереннее',B2:'Понимай оттенки'};
const ORDER=['hello','cafe','family','routine','home','city','shopping','weekend','travel','health','experiences','future','stories','advice','environment','possibilities','reported','arguments','regrets','nuance'];
LESSONS.sort((a,b)=>ORDER.indexOf(a.id)-ORDER.indexOf(b.id));
const BASICS={
 hello:{title:'Знакомство: am, is и are',rule:'В английском предложении нужен глагол. Для «быть» в настоящем времени используй am с I, is с he/she/it, are с you/we/they. My name — единственное число, значит is.',tips:['I am = I’m; you are = you’re.','How are you? — вопрос о самочувствии или делах.'],examples:[['My name is Alex.','Меня зовут Алекс.'],["I'm fine, thanks.",'У меня всё хорошо, спасибо.'],['Nice to meet you.','Рад познакомиться.']]},
 cafe:{title:'Вежливый заказ: I would like',rule:'I would like (I’d like) означает «я бы хотел». Some используют с неисчисляемыми словами water, tea, milk, когда точное количество не важно. A cup of… уточняет порцию.',tips:['Добавь please, чтобы просьба звучала вежливо.','With — с; without — без.'],examples:[['I would like some tea.','Я бы хотел чаю.'],['A coffee with milk, please.','Кофе с молоком, пожалуйста.'],['The bill, please.','Счёт, пожалуйста.']]},
 family:{title:'Семья: have и притяжательные слова',rule:'Have означает «иметь». С I/you/we/they используй have, с he/she/it — has. My, your, his и her показывают, кому принадлежит предмет, и стоят перед существительным.',tips:['Her — её; his — его; their — их.','Перед одним исчисляемым предметом часто нужен a/an.'],examples:[['I have a brother.','У меня есть брат.'],['She is a teacher.','Она учительница.'],['This is her book.','Это её книга.']]},
 routine:{title:'Present Simple: привычки',rule:'Present Simple описывает регулярные действия. После he/she/it к большинству глаголов добавляют -s. Для отрицания нужны don’t или doesn’t + глагол без -s.',tips:['Usually обычно стоит перед основным глаголом.','At seven — в семь; on Sundays — по воскресеньям.'],examples:[['He walks to work every day.','Он ходит на работу пешком каждый день.'],['I usually have breakfast at home.','Я обычно завтракаю дома.'],["I don't work on Sundays.",'Я не работаю по воскресеньям.']]},
 city:{title:'Направления и вопросы с where',rule:'Where означает «где». С глаголом be в вопросе меняй порядок: Where is the station? Для указаний используй начальную форму: turn, go, stop.',tips:['Next to — рядом с; opposite — напротив.','How do I get to…? — как добраться до…?'],examples:[['Turn left at the bank.','Поверните налево у банка.'],['The park is next to the station.','Парк рядом со станцией.'],['Where is the nearest station?','Где ближайшая станция?']]},
 shopping:{title:'Сравнение и покупки',rule:'У коротких прилагательных сравнительная степень обычно образуется с -er: cheap → cheaper, small → smaller. Для длинных слов часто нужен more: more expensive.',tips:['Than — чем. These — эти, с множественным числом.','Can I…? — можно мне…?'],examples:[['This bag is cheaper than that one.','Эта сумка дешевле той.'],['Do you have a smaller size?','Есть размер поменьше?'],['Can I pay by card?','Можно заплатить картой?']]},
 weekend:{title:'Планы и приглашения',rule:'Be going to + глагол выражает намерение. Would you like to…? — вежливое приглашение. После enjoy используй -ing: enjoy swimming.',tips:['Let us / let’s + глагол — давай / давайте.','I’d love to! — с удовольствием!'],examples:[['We are going to watch a film.','Мы собираемся посмотреть фильм.'],['Would you like to join us?','Хочешь к нам присоединиться?'],['I enjoy swimming.','Мне нравится плавать.']]},
 travel:{title:'Поездки: прошлое и бронирование',rule:'Past Simple нужен для завершённых событий в прошлом. У правильных глаголов окончание -ed, а неправильные формы запоминают: go → went. For может обозначать длительность.',tips:['Last summer — прошлым летом, сигнал завершённого прошлого.','Luggage — неисчисляемое: my luggage is, без -s.'],examples:[['We went to London last summer.','Прошлым летом мы ездили в Лондон.'],['I have a reservation for two nights.','У меня бронирование на две ночи.'],['My luggage is heavy.','Мой багаж тяжёлый.']]}
};
LESSONS.forEach(lesson=>{lesson.grammar=lesson.grammar||BASICS[lesson.id];});
const PLACEMENT=[
 {...choice('Выбери правильную фразу',['She is my friend.','She are my friend.','She am my friend.','She be my friend.'],'She is my friend.','С she нужен is.'),level:'A1'},
 {...gap('Вставь пропущенное слово','I ___ a brother.',['have'],'С I используется have.'),level:'A1'},
 {...choice('Что означает «I usually walk to work»?',['Я обычно хожу на работу пешком','Я сейчас еду на работу','Я работал вчера','Я редко гуляю после работы'],'Я обычно хожу на работу пешком','Usually — обычно; walk — идти пешком.'),level:'A1'},
 {...gap('Используй go в прошедшем времени','Last year, we ___ to Spain.',['went'],'Прошедшая форма go — went.'),level:'A2'},
 {...choice('Выбери правильное сравнение',['This bag is cheaper than that one.','This bag is more cheap that one.','This bag is cheapest than that one.','This bag is cheaper that one.'],'This bag is cheaper than that one.','Cheaper than — дешевле, чем.'),level:'A2'},
 {...choice('Как дать совет?',['You should get some rest.','You should to get some rest.','You should gets some rest.','You should getting some rest.'],'You should get some rest.','После should — начальная форма без to.'),level:'A2'},
 {...gap('Используй третью форму be','Have you ever ___ to Italy?',['been'],'Present Perfect: have + been.'),level:'B1'},
 {...choice('Выбери правильное будущее условие',['If it rains, we will stay home.','If it will rain, we will stay home.','If it rain, we stayed home.','If it rained, we will staying home.'],'If it rains, we will stay home.','После if — Present Simple.'),level:'B1'},
 {...choice('Что означает «You don’t have to come early»?',['Тебе необязательно приходить рано','Тебе запрещено приходить рано','Ты обязан прийти пораньше','Ты не можешь прийти рано'],'Тебе необязательно приходить рано','Don’t have to — нет необходимости.'),level:'B1'},
 {...choice('Выбери верную конструкцию',['Despite the rain, we went out.','Despite it was raining, we went out.','Despite of the rain, we went out.','Despite to rain, we went out.'],'Despite the rain, we went out.','После despite — существительное или -ing.'),level:'B2'},
 {...gap('Передай слова «I will call»','She said she ___ call.',['would'],'В прошлой косвенной речи will обычно меняется на would.'),level:'B2'},
 {...choice('Выбери сожаление о прошлом',['I wish I had listened.','I wish I will listen yesterday.','I wish I have listen.','I wish I had listen.'],'I wish I had listened.','Wish + Past Perfect — сожаление о прошлом.'),level:'B2'}
];
function dateKey(date=new Date()){return date.getFullYear()+'-'+String(date.getMonth()+1).padStart(2,'0')+'-'+String(date.getDate()).padStart(2,'0');}
function shiftDate(key,delta){const d=new Date(key+'T12:00:00');d.setDate(d.getDate()+delta);return dateKey(d);}
function cleanState(raw){
 const result={version:3,xp:0,dialogueAwards:{},days:{},lessons:{},recentQuestions:[],goal:30,placement:{completed:false,level:null,score:0,date:''}};
 if(!raw||typeof raw!=='object'||Array.isArray(raw))return result;
 if(raw.dialogueAwards&&typeof raw.dialogueAwards==='object')Object.entries(raw.dialogueAwards).forEach(([id,xp])=>{if(/^dialogue-[a-z0-9-]{1,90}$/i.test(id)&&Number.isInteger(xp)&&xp>=5&&xp<=40)result.dialogueAwards[id]=xp;});
 result.recentQuestions=Array.isArray(raw.recentQuestions)?[...new Set(raw.recentQuestions.filter(k=>typeof k==='string'&&k.length>0&&k.length<=500))].slice(-QUESTION_HISTORY_LIMIT):[];
 result.xp=number(raw.xp);result.goal=[30,50,100].includes(Number(raw.goal))?Number(raw.goal):30;
 if(raw.days&&typeof raw.days==='object')Object.entries(raw.days).filter(([k,v])=>/^\d{4}-\d{2}-\d{2}$/.test(k)&&v&&typeof v==='object'&&!Number.isNaN(new Date(k+'T12:00:00').getTime())&&dateKey(new Date(k+'T12:00:00'))===k&&k<=dateKey()).sort(([a],[b])=>b.localeCompare(a)).slice(0,730).forEach(([k,v])=>{result.days[k]={xp:number(v.xp,5000),lessons:number(v.lessons,1000),reviews:number(v.reviews,1000),speaking:number(v.speaking,1000)};});
 LESSONS.forEach(lesson=>{const value=raw.lessons&&raw.lessons[lesson.id];if(value&&typeof value==='object'){const best=number(value.best,8),bestPercent=Number.isFinite(value.bestPercent)?number(value.bestPercent,100):Math.round(Math.min(best,6)/6*100);result.lessons[lesson.id]={passed:Boolean(value.passed)&&bestPercent>=70,best,bestPercent,attempts:number(value.attempts,100000),completedAt:typeof value.completedAt==='string'?value.completedAt.slice(0,32):''};}});
 const p=raw.placement;if(p&&p.completed&&LEVELS.includes(p.level)){result.placement={completed:true,level:p.level,score:number(p.score,12),date:typeof p.date==='string'?p.date.slice(0,32):'',bands:{}};LEVELS.forEach(level=>{result.placement.bands[level]=number(p.bands&&p.bands[level],3);});}
 return result;
}
let state;try{state=cleanState(JSON.parse(localStorage.getItem(STORAGE_KEY)));}catch(_){state=cleanState(null);}
let selectedLevel=state.placement.level||'A1',session=null,returnFocus=null,initialized=false,storageErrorShown=false,pendingLaunch=null,generation=null,generationSequence=0;
function bridge(){return window.ReadFoxBridge||{};}
function notify(message,error=false){if(bridge().toast)bridge().toast(message,error);}
function sound(kind){try{window.ReadFoxSound?.play(kind);}catch(_){}}
function save(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));}catch(_){if(!storageErrorShown){notify('Не удалось сохранить прогресс. Проверь место в браузере и экспортируй данные.',true);storageErrorShown=true;}}render();window.dispatchEvent(new CustomEvent('readfox:academy-change'));}
function today(){const key=dateKey();if(!state.days[key])state.days[key]={xp:0,lessons:0,reviews:0,speaking:0};return state.days[key];}
function streak(){let k=dateKey();if(!state.days[k]?.xp)k=shiftDate(k,-1);let count=0;while(state.days[k]?.xp&&count<731){count++;k=shiftDate(k,-1);}return count;}
function bestStreak(){let best=0,current=0,previous='';Object.keys(state.days).filter(k=>state.days[k].xp>0).sort().forEach(k=>{current=previous&&shiftDate(previous,1)===k?current+1:1;best=Math.max(best,current);previous=k;});return best;}
function earnedLessonCount(){return LESSONS.filter(l=>state.lessons[l.id]?.passed).length;}
function isUnlocked(index){
 if(index<0||index>=LESSONS.length||!state.placement.completed)return false;
 const lesson=LESSONS[index],tier=LEVELS.indexOf(lesson.level),startTier=LEVELS.indexOf(state.placement.level);
 return Boolean(state.lessons[lesson.id]?.passed)||tier<startTier||index===0||(tier===startTier&&(index===0||LESSONS[index-1].level!==lesson.level))||Boolean(state.lessons[LESSONS[index-1]?.id]?.passed);
}
function currentLesson(){const first=LESSONS.findIndex(l=>l.level===(state.placement.level||'A1'));return LESSONS.slice(first).find((l,i)=>isUnlocked(first+i)&&!state.lessons[l.id]?.passed)||LESSONS.find((l,i)=>isUnlocked(i)&&!state.lessons[l.id]?.passed)||LESSONS[first]||LESSONS[0];}
function getStats(){try{return bridge().getStats?.()||{learning:0,known:0,texts:0,due:0};}catch(_){return {learning:0,known:0,texts:0,due:0};}}
function personalWords(){try{return (bridge().getWords?.()||[]).filter(w=>w&&typeof w.key==='string'&&w.key.trim()&&typeof w.translation==='string'&&w.translation.trim());}catch(_){return [];}}
function setText(id,value){if($(id))$(id).textContent=value;}
function setPercent(id,value){if(!$(id))return;const bounded=Math.min(100,Math.max(0,value));$(id).style.width=bounded+'%';$(id).setAttribute('aria-valuenow',String(Math.round(bounded)));}
function renderPath(){
 if(!$('learningPath'))return;
 const current=currentLesson(),levelLessons=LESSONS.filter(l=>l.level===selectedLevel),completed=levelLessons.filter(l=>state.lessons[l.id]?.passed).length;
 $('learningPath').innerHTML='<div class="path-level-tabs" role="tablist" aria-label="Уровни английского">'+LEVELS.map(level=>'<button type="button" role="tab" class="path-level-tab '+(level===selectedLevel?'is-selected':'')+'" data-level="'+level+'" aria-selected="'+(level===selectedLevel)+'" aria-controls="learningLevelPanel">'+level+'<small>'+LESSONS.filter(l=>l.level===level&&state.lessons[l.id]?.passed).length+'/5</small></button>').join('')+'</div>'+(!state.placement.completed?'<div class="placement-notice"><span>'+icon('compass')+'</span><div><strong>Сначала найдём твою точку старта</strong><p>12 коротких вопросов помогут подобрать подходящий уровень. Твой прежний прогресс сохранится.</p></div><button class="btn" data-action="placement">Пройти тест</button></div>':'')+'<section class="path-unit" id="learningLevelPanel" role="tabpanel" aria-label="'+selectedLevel+'"><div class="path-unit-heading"><span class="path-unit-badge">'+selectedLevel+'</span><div><h3>'+LEVEL_NAMES[selectedLevel]+'</h3><p>5 тем · новые задания ИИ, частотные и твои слова</p></div><span class="path-unit-count">'+completed+'/5</span></div><div class="path-steps">'+levelLessons.map(lesson=>{const index=LESSONS.indexOf(lesson),done=state.lessons[lesson.id]?.passed,unlocked=isUnlocked(index),status=done?'is-done':!unlocked?'is-locked':current.id===lesson.id?'is-current':'';return '<button type="button" class="path-step '+status+'" data-lesson="'+lesson.id+'" '+(state.placement.completed&&!unlocked?'disabled ':'')+'aria-label="'+esc(lesson.title+(done?', пройдено':unlocked?', начать урок':state.placement.completed?', сначала предыдущий урок':', сначала входной тест'))+'"><span class="path-node">'+icon(done?'check':unlocked?lesson.icon:'lock')+'</span><span class="path-label"><strong>'+esc(lesson.title)+'</strong><small>'+(done?'Можно повторить':unlocked?'Грамматика + 6 заданий ИИ':state.placement.completed?'После предыдущей темы':'После входного теста')+'</small></span>'+(status==='is-current'?'<span class="path-start-label">Твой следующий шаг</span>':'')+'</button>';}).join('')+'</div></section>';
}
