function makeSession(kind,lesson,questions,stage='questions'){return {kind,lesson,questions,stage,index:0,correct:0,wrong:[],retry:false,retryIndex:0,retryCorrect:0,checked:false,answer:null,selected:[],tileOrder:[],awarded:false,bands:{A1:0,A2:0,B1:0,B2:0}};}
function optionsShuffled(questions){return questions.map(q=>({...q,options:q.options?shuffle(q.options):undefined}));}
function reviewQuestion(w,index,pool){const options=shuffle([w.translation,...shuffle(pool.filter(t=>normal(t)!==normal(w.translation))).slice(0,3)]),explanation='«'+w.key+'» — '+w.translation+(w.example?'. '+w.example:'.'),q=index%2?listen(w.key,options,w.translation,explanation):choice('Твоё слово: «'+w.key+'»',options,w.translation,explanation);return {...q,reviewKey:w.key,personal:true};}
function wordsForLesson(lesson){const keys=new Set(lesson.words.map(w=>normal(w.key)));const list=personalWords().filter(w=>!keys.has(normal(w.key))&&/^[a-z][a-z'’ -]{0,69}$/i.test(w.key.trim())&&/[а-яё]/i.test(w.translation));list.sort((a,b)=>{const dueA=Number(a.nextReviewAt)||0,dueB=Number(b.nextReviewAt)||0,rankA=(dueA<=Date.now()?0:2)+(a.status==='learning'?0:1),rankB=(dueB<=Date.now()?0:2)+(b.status==='learning'?0:1);return rankA-rankB||dueA-dueB;});return list.slice(0,2);}
function translationPool(words){return [...new Set([...words.map(w=>w.translation),...LESSONS.flatMap(l=>l.words.map(w=>w.translation))])];}
function questionKey(q){return String(q.sentence||q.audio||q.answer||q.prompt||'').normalize('NFKC').toLowerCase().replace(/[’‘]/g,"'").replace(/[^\p{L}\p{N}']/gu,' ').replace(/\s+/g,' ').trim();}
function learnerLevel(){return LEVELS[Math.max(LEVELS.indexOf(state.placement.level||'A1'),...LESSONS.filter(l=>state.lessons[l.id]?.passed).map(l=>LEVELS.indexOf(l.level)))];}
