 if(q.type==='input'||q.type==='gap')exercise+='<label class="lesson-input-label" for="lessonAnswer">Твой ответ на английском</label><input id="lessonAnswer" class="lesson-input" type="text" placeholder="Напиши здесь…" autocomplete="off" autocapitalize="off" spellcheck="false" maxlength="240" lang="en"><p class="lesson-hint">Регистр и знаки препинания не влияют на результат.</p>';
